mapper.select:
select ric.PROD_ID prodId, rpi.PROD_NAME prodName, ric.ACCOUNT_TYPE accountType, ric.ACCOUNT_NUM accountNum, ric.ACCOUNT_NAME accountName, ric.ACCOUNT_OPENER accountOpener, ric.STATUS status, ric.UPDATE_USER updateUser, ric.UPDATE_TIME updateTime, cie.ERR_MSG errmsg from REP_INVEST_ACCOUNT ric left join REP_PROD_INFO rpi on rpi.PROD_ID = ric.PROD_ID left join CHB_INTERF_ERRODATA cie on cie.DATAID = ric.PROD_ID and cie.INTERF_TYPE = 'REP_INVEST_ACCOUNT'
#{item,jdbcType=VARCHAR}
and ric.ACCOUNT_NUM = #{accountNum,jdbcType=VARCHAR}
and ric.ACCOUNT_NAME = #{accountName,jdbcType=VARCHAR}
and ric.STATUS = #{status,jdbcType=VARCHAR}

mapper.delete:
		update REP_INVEST_ACCOUNT
		set STATUS = 'D'
		where PROD_ID = #{prodId,jdbcType=VARCHAR}
          and ACCOUNT_NUM = #{accountNum,jdbcType=VARCHAR}
